ALTER TABLE public.portal_charge_requests ADD COLUMN IF NOT EXISTS stripe_payment_method_id text;
CREATE OR REPLACE FUNCTION public.guard_portal_charge_reservation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.bookings; a public.card_authorizations; BEGIN SELECT * INTO b FROM public.bookings WHERE id=NEW.booking_id FOR UPDATE; SELECT * INTO a FROM public.card_authorizations WHERE id=NEW.authorization_id FOR UPDATE; IF b.user_id IS DISTINCT FROM NEW.user_id OR a.user_id IS DISTINCT FROM NEW.user_id OR a.booking_id IS DISTINCT FROM b.id OR a.revoked_at IS NOT NULL OR a.amount_cents IS DISTINCT FROM NEW.amount_cents OR b.payment_status IN ('paid','refunded') OR b.status IN ('cancelled','canceled','no_show') THEN RAISE EXCEPTION 'Appointment or authorization changed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER portal_charge_reservation_guard BEFORE INSERT ON public.portal_charge_requests FOR EACH ROW EXECUTE FUNCTION public.guard_portal_charge_reservation();
CREATE OR REPLACE FUNCTION public.guard_portal_authorization_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM 1 FROM public.bookings WHERE id=NEW.booking_id FOR UPDATE; IF EXISTS(SELECT 1 FROM public.portal_charge_requests WHERE booking_id=NEW.booking_id) THEN RAISE EXCEPTION 'Charge already started'; END IF; RETURN NEW; END $$;
CREATE TRIGGER portal_authorization_change_guard BEFORE INSERT OR UPDATE ON public.card_authorizations FOR EACH ROW EXECUTE FUNCTION public.guard_portal_authorization_change();
CREATE OR REPLACE FUNCTION public.guard_reserved_booking_price() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF (NEW.total_price IS DISTINCT FROM OLD.total_price OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.deposit_amount IS DISTINCT FROM OLD.deposit_amount OR NEW.guest_email IS DISTINCT FROM OLD.guest_email OR NEW.status IN ('canceled','cancelled')) AND EXISTS(SELECT 1 FROM public.portal_charge_requests WHERE booking_id=OLD.id AND status NOT IN ('succeeded','canceled')) THEN RAISE EXCEPTION 'Resolve the pending card charge before changing this appointment'; END IF; RETURN NEW; END $$;
CREATE TRIGGER portal_reserved_booking_guard BEFORE UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION public.guard_reserved_booking_price();
CREATE TABLE public.portal_reminder_deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES public.bookings(id),scheduled_date date NOT NULL,scheduled_time time NOT NULL,channel text NOT NULL CHECK(channel IN ('email','sms')),reminder_type text NOT NULL,status text NOT NULL DEFAULT 'reserved',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(booking_id,scheduled_date,scheduled_time,channel,reminder_type));
GRANT SELECT ON public.portal_reminder_deliveries TO authenticated; GRANT ALL ON public.portal_reminder_deliveries TO service_role;
ALTER TABLE public.portal_reminder_deliveries ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins read reminder deliveries" ON public.portal_reminder_deliveries FOR SELECT TO authenticated USING(public.is_admin());